DECLARE
  v_actor record;
  v_affiliate record;
  v_program_id uuid;
  v_clean_tipo text := lower(trim(coalesce(p_tipo, '')));
  v_motivo text := trim(coalesce(p_motivo, ''));
  v_client_id uuid;
BEGIN
  PERFORM public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  PERFORM public.gsa_admin_assert_module('afiliados');
  SELECT * INTO v_actor FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token) LIMIT 1;

  IF p_afiliado_id IS NULL THEN RAISE EXCEPTION 'Afiliado não informado.'; END IF;
  IF p_valor IS NULL OR p_valor = 0 THEN RAISE EXCEPTION 'Valor do ajuste deve ser diferente de zero.'; END IF;
  IF length(v_motivo) < 3 THEN RAISE EXCEPTION 'Informe o motivo do ajuste (mínimo 3 caracteres).'; END IF;

  SELECT * INTO v_affiliate FROM public.gsa_afiliados WHERE id = p_afiliado_id;
  IF v_affiliate.id IS NULL THEN RAISE EXCEPTION 'Afiliado não encontrado.'; END IF;
  v_client_id := v_affiliate.cliente_id;

  IF v_clean_tipo = 'pontos' THEN
    UPDATE public.clientes
    SET pontos = greatest(coalesce(pontos, 0) + p_valor, 0),
        updated_at = now()
    WHERE id = v_client_id;

    INSERT INTO public.gsa_afiliado_pontos_eventos(cliente_id, afiliado_id, tipo, pontos_assinados, metadata)
    VALUES (
      v_client_id,
      p_afiliado_id,
      'ajuste',
      p_valor,
      jsonb_build_object('descricao', v_motivo, 'autor', v_actor.ator_nome)
    );

  ELSIF v_clean_tipo IN ('comissao', 'saldo', 'carteira') THEN
    SELECT id INTO v_program_id FROM public.gsa_afiliado_programas WHERE ativo ORDER BY created_at ASC LIMIT 1;
    IF v_program_id IS NULL THEN
      SELECT id INTO v_program_id FROM public.gsa_afiliado_programas ORDER BY created_at ASC LIMIT 1;
    END IF;
    IF v_program_id IS NULL THEN RAISE EXCEPTION 'Nenhum programa de afiliado cadastrado.'; END IF;

    INSERT INTO public.gsa_afiliado_comissoes(
      afiliado_id,
      programa_id,
      conversao_id,
      percentual_snapshot,
      base_elegivel_snapshot,
      valor,
      status,
      disponivel_em
    ) VALUES (
      p_afiliado_id,
      v_program_id,
      NULL,
      100,
      abs(p_valor),
      p_valor,
      'disponivel',
      now()
    );

  ELSE
    RAISE EXCEPTION 'Tipo de ajuste inválido. Utilize "pontos" ou "comissao".';
  END IF;

  INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
  VALUES (
    v_client_id,
    CASE WHEN p_valor > 0 THEN 'Ajuste de Crédito Realizado' ELSE 'Ajuste de Débito Realizado' END,
    CASE WHEN v_clean_tipo = 'pontos'
      THEN format('Foi realizado um ajuste de %s%s pontos no seu saldo. Motivo: %s', CASE WHEN p_valor > 0 THEN '+' ELSE '' END, p_valor, v_motivo)
      ELSE format('Foi realizado um ajuste de %sR$ %s no seu saldo de comissões. Motivo: %s', CASE WHEN p_valor > 0 THEN '+' ELSE '' END, to_char(abs(p_valor), 'FM999G999G990D00'), v_motivo)
    END,
    'afiliados', CASE WHEN v_clean_tipo = 'pontos' THEN 'pontos' ELSE 'comissoes' END, 'cliente', 'ajuste_manual_afiliado'
  );

  PERFORM public.gsa_admin_write_audit(
    'afiliados',
    'AJUSTE_MANUAL_BALANCO_AFILIADO',
    'gsa_afiliados',
    p_afiliado_id,
    jsonb_build_object('tipo', v_clean_tipo, 'valor', p_valor, 'motivo', v_motivo, 'ator', v_actor.ator_nome)
  );

  RETURN jsonb_build_object('success', true, 'tipo', v_clean_tipo, 'valor', p_valor);
END;

DECLARE
  v_actor record;
  v_result jsonb;
BEGIN
  SELECT * INTO v_actor
  FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token)
  LIMIT 1;

  IF p_pontos = 0 OR abs(p_pontos) > 1000000 THEN RAISE EXCEPTION 'Ajuste de pontos invalido.'; END IF;
  IF nullif(trim(p_descricao), '') IS NULL THEN RAISE EXCEPTION 'Informe o motivo do ajuste.'; END IF;

  v_result := public.gsa_apply_points_internal(
    p_cliente_id,
    p_pontos,
    trim(p_descricao) || ' [POR: ' || v_actor.ator_nome || ']',
    'ajuste_manual',
    NULL,
    true
  );

  INSERT INTO public.sistema_logs(acao, detalhes, ator_tipo, ator_id, ator_nome)
  VALUES (
    'AJUSTE_PONTOS_CLIENTE',
    jsonb_build_object('cliente_id', p_cliente_id, 'pontos', p_pontos, 'motivo', trim(p_descricao))::text,
    v_actor.ator_tipo, v_actor.ator_id, v_actor.ator_nome
  );
  RETURN v_result;
END;

DECLARE
  v_actor record;
  v_cliente clientes%rowtype;
  v_tipo text := coalesce(nullif(trim(p_tipo), ''), 'entrada');
  v_valor numeric := round(coalesce(p_valor, 0), 2);
  v_adjustment numeric;
  v_novo_saldo numeric;
  v_descricao text;
BEGIN
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'Valor do ajuste deve ser maior que zero.';
  END IF;

  IF v_tipo NOT IN ('entrada', 'saida') THEN
    RAISE EXCEPTION 'Tipo de ajuste invalido.';
  END IF;

  SELECT * INTO v_actor
  FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token)
  LIMIT 1;

  SELECT * INTO v_cliente
  FROM public.clientes
  WHERE id = p_cliente_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  v_adjustment := CASE WHEN v_tipo = 'entrada' THEN v_valor ELSE -v_valor END;
  v_novo_saldo := round(coalesce(v_cliente.saldo_carteira, 0) + v_adjustment, 2);
  v_descricao := coalesce(nullif(trim(p_descricao), ''), 'Lancamento manual de ' || CASE WHEN v_tipo = 'entrada' THEN 'credito' ELSE 'debito' END) || ' [POR: ' || v_actor.ator_nome || ']';

  UPDATE public.clientes
     SET saldo_carteira = v_novo_saldo,
         updated_at = now()
   WHERE id = p_cliente_id;

  INSERT INTO public.carteira_lancamentos(cliente_id, valor, tipo, descricao)
  VALUES (
    p_cliente_id,
    v_valor,
    CASE WHEN v_tipo = 'entrada' THEN 'credito' ELSE 'debito' END,
    v_descricao
  );

  INSERT INTO public.extrato_financeiro(cliente_id, tipo, valor, descricao, saldo_resultante)
  VALUES (
    p_cliente_id,
    v_tipo,
    v_valor,
    v_descricao,
    v_novo_saldo
  );

  RETURN jsonb_build_object(
    'success', true,
    'cliente_id', p_cliente_id,
    'saldo_anterior', coalesce(v_cliente.saldo_carteira, 0),
    'saldo_atual', v_novo_saldo,
    'ajuste', v_adjustment
  );
END;

DECLARE
  v_actor record;
  v_status text := nullif(trim(coalesce(p_status, '')), '');
BEGIN
  IF v_status NOT IN ('ativo', 'inativo') THEN
    RAISE EXCEPTION 'Status invalido.';
  END IF;

  SELECT * INTO v_actor
  FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token)
  LIMIT 1;

  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = p_cliente_id FOR UPDATE) THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  UPDATE public.clientes
     SET status = v_status,
         cadastro_aprovado = CASE WHEN v_status = 'ativo' THEN true ELSE cadastro_aprovado END,
         updated_at = now()
   WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', true,
    'cliente_id', p_cliente_id,
    'status', v_status,
    'patch', jsonb_build_object(
      'status', v_status,
      'cadastro_aprovado', CASE WHEN v_status = 'ativo' THEN true ELSE NULL END
    ),
    'ator_nome', v_actor.ator_nome
  );
END;

DECLARE
  v_actor jsonb;
  v_orc public.orcamentos%ROWTYPE;
  v_result jsonb;
BEGIN
  v_actor := public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  PERFORM public.gsa_admin_assert_module('operacoes');

  IF p_orcamento_id IS NULL THEN
    RAISE EXCEPTION 'ID do or??amento ?? obrigat??rio.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_orc FROM public.orcamentos WHERE id = p_orcamento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Or??amento n??o encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_result := public.aprovar_orcamento_cliente(p_orcamento_id, v_orc.cliente_id);

  PERFORM public.gsa_admin_write_audit(
    'operacoes',
    'APROVAR_ORCAMENTO',
    'orcamentos',
    p_orcamento_id,
    jsonb_build_object('kind', p_approval_kind, 'request_id', p_request_id, 'result', v_result)
  );

