DECLARE
  v_actor record;
  v_cobranca cobrancas%rowtype;
  v_fatura_ref text;
  v_canceladas integer := 0;
BEGIN
  SELECT * INTO v_actor
  FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token)
  LIMIT 1;

  SELECT * INTO v_cobranca
  FROM public.cobrancas
  WHERE id = p_cobranca_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cobranca nao encontrada.';
  END IF;

  SELECT coalesce(codigo_fatura, v_cobranca.fatura_id::text)
    INTO v_fatura_ref
  FROM public.faturas
  WHERE id = v_cobranca.fatura_id;

  v_fatura_ref := coalesce(v_fatura_ref, left(p_cobranca_id::text, 8));

  UPDATE public.faturas
     SET status = 'cancelado',
         observacoes = 'Acordo cancelado em ' || to_char(now(), 'DD/MM/YYYY HH24:MI') || ' [POR: ' || v_actor.ator_nome || ']'
   WHERE cliente_id = v_cobranca.cliente_id
     AND observacoes ILIKE ('%' || v_fatura_ref || '%')
     AND status IN ('pendente', 'vencida', 'pendente_pagamento');

  GET DIAGNOSTICS v_canceladas = ROW_COUNT;

  UPDATE public.cobranca_acordo_parcelas
     SET status = 'cancelado'
   WHERE cobranca_id = p_cobranca_id
     AND status = 'pendente';

  IF v_cobranca.fatura_id IS NOT NULL THEN
    UPDATE public.faturas
       SET status = 'vencida',
           observacoes = 'Reativada apos cancelamento de acordo manual em ' || to_char(now(), 'DD/MM/YYYY HH24:MI') || ' [POR: ' || v_actor.ator_nome || ']'
     WHERE id = v_cobranca.fatura_id;
  END IF;

  UPDATE public.cobrancas
     SET status = 'pendente',
         nivel_cobranca = 1,
         valor_pago = 0
   WHERE id = p_cobranca_id;

  INSERT INTO public.cobranca_historico(cobranca_id, tipo_acao, descricao, canal)
  VALUES (
    p_cobranca_id,
    'mudanca_status',
    'Acordo CANCELADO MANUALMENTE. Faturas de parcelas invalidadas e divida original reativada. [POR: ' || v_actor.ator_nome || ']',
    'sistema'
  );

  RETURN jsonb_build_object(
    'success', true,
    'cobranca_id', p_cobranca_id,
    'faturas_canceladas', v_canceladas
  );
END;

DECLARE
  v_clean_link text := trim(COALESCE(p_link_ativacao, ''));
  v_resgate record;
BEGIN
  PERFORM public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  PERFORM public.gsa_admin_assert_module('parceiros');

  IF p_resgate_id IS NULL THEN
    RAISE EXCEPTION 'ID do resgate ?? obrigat??rio.' USING ERRCODE = '22023';
  END IF;

  IF v_clean_link = '' THEN
    RAISE EXCEPTION 'Informe o link de ativa????o gerado no site do parceiro.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.parceiros_resgates
     SET link_ativacao = v_clean_link,
         status = 'concluido',
         data_ativacao = now()
   WHERE id = p_resgate_id
  RETURNING * INTO v_resgate;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Resgate n??o encontrado.' USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'resgate', to_jsonb(v_resgate)
  );
END;

DECLARE
  v_code text;
  v_id uuid;
  v_actor uuid;
  v_attempt integer;
BEGIN
  PERFORM public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  IF p_tool_id IS NOT NULL AND p_tool_id NOT IN ('termination','retirement','vacation','thirteenth','benefits','bpc') THEN
    RAISE EXCEPTION 'Calculadora inválida' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    RAISE EXCEPTION 'A validade precisa estar no futuro' USING ERRCODE = '22023';
  END IF;

  BEGIN
    SELECT public.gsa_current_actor_id() INTO v_actor;
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;

  FOR v_attempt IN 1..5 LOOP
    v_code := 'GSA-PRO-' || upper(encode(gen_random_bytes(10), 'hex'));
    BEGIN
      INSERT INTO public.gsa_calculator_pro_vouchers(
        code_hash, code_hint, tool_id, expires_at, observacoes, created_by
      ) VALUES (
        encode(digest(upper(v_code), 'sha256'), 'hex'),
        right(v_code, 6),
        p_tool_id,
        p_expires_at,
        nullif(btrim(p_observacoes), ''),
        v_actor
      ) RETURNING id INTO v_id;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF v_attempt = 5 THEN RAISE; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'code', v_code);
END;

DECLARE
  v_action text := lower(trim(coalesce(p_action, '')));
  v_payout public.gsa_afiliado_saques%rowtype;
  v_remaining numeric(14,2);
  v_item record;
  v_take numeric(14,2);
  v_client_id uuid;
BEGIN
  PERFORM public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  PERFORM public.gsa_admin_assert_module('afiliados');
  SELECT * INTO v_payout FROM public.gsa_afiliado_saques WHERE id = p_payout_id FOR UPDATE;
  IF v_payout.id IS NULL THEN RAISE EXCEPTION 'Saque não encontrado.'; END IF;

  SELECT cliente_id INTO v_client_id FROM public.gsa_afiliados WHERE id = v_payout.afiliado_id;

  IF v_action = 'approve' THEN
    IF v_payout.status <> 'solicitado' THEN RAISE EXCEPTION 'Somente saques solicitados podem ser aprovados.'; END IF;
    UPDATE public.gsa_afiliado_saques SET status = 'aprovado', aprovado_em = coalesce(p_paid_at, now()), notas = nullif(left(trim(coalesce(p_notes, '')), 1000), ''), updated_at = now() WHERE id = v_payout.id;

    IF v_client_id IS NOT NULL THEN
      INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
      VALUES (
        v_client_id,
        'Solicitação de Saque Aprovada',
        format('Sua solicitação de saque de R$ %s foi aprovada e está em processamento de pagamento.', to_char(v_payout.valor, 'FM999G999G990D00')),
        'afiliados', 'saques', 'cliente', 'aprovacao_saque'
      );
    END IF;

  ELSIF v_action = 'reject' THEN
    IF v_payout.status NOT IN ('solicitado','aprovado') THEN RAISE EXCEPTION 'Este saque não pode ser rejeitado.'; END IF;
    UPDATE public.gsa_afiliado_saques SET status = 'rejeitado', rejeitado_em = coalesce(p_paid_at, now()), notas = nullif(left(trim(coalesce(p_notes, '')), 1000), ''), updated_at = now() WHERE id = v_payout.id;

    IF v_client_id IS NOT NULL THEN
      INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
      VALUES (
        v_client_id,
        'Solicitação de Saque Recusada',
        format('Sua solicitação de saque de R$ %s foi recusada.%s', to_char(v_payout.valor, 'FM999G999G990D00'), CASE WHEN p_notes IS NOT NULL THEN ' Motivo: ' || p_notes ELSE '' END),
        'afiliados', 'saques', 'cliente', 'rejeicao_saque'
      );
    END IF;

  ELSIF v_action = 'mark_paid' THEN
    IF v_payout.status <> 'aprovado' THEN RAISE EXCEPTION 'Aprove o saque antes de confirmar o pagamento.'; END IF;
    v_remaining := v_payout.valor;
    FOR v_item IN
      SELECT id, valor, pago_valor FROM public.gsa_afiliado_comissoes
      WHERE afiliado_id = v_payout.afiliado_id AND status = 'disponivel' AND pago_valor < valor
      ORDER BY disponivel_em, created_at FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_take := least(v_remaining, v_item.valor - v_item.pago_valor);
      UPDATE public.gsa_afiliado_comissoes
         SET pago_valor = pago_valor + v_take,
             status = CASE WHEN pago_valor + v_take >= valor THEN 'paga' ELSE 'disponivel' END,
             paga_em = CASE WHEN pago_valor + v_take >= valor THEN coalesce(p_paid_at, now()) ELSE paga_em END,
             updated_at = now()
       WHERE id = v_item.id;
      v_remaining := v_remaining - v_take;
    END LOOP;

    IF v_remaining > 0 THEN
      PERFORM set_config('gsa.credit_release', 'on', true);
      UPDATE public.clientes
         SET saldo_carteira = greatest(saldo_carteira - v_remaining, 0)
       WHERE id = v_client_id;
      v_remaining := 0;
    END IF;

    INSERT INTO public.gsa_afiliado_comissao_eventos(afiliado_id, saque_id, tipo, valor_assinado, efetivo_em, metadata)
    VALUES (v_payout.afiliado_id, v_payout.id, 'saque', -v_payout.valor, coalesce(p_paid_at, now()), jsonb_build_object('notas', p_notes))
    ON CONFLICT DO NOTHING;

    UPDATE public.gsa_afiliado_saques SET status = 'pago', pago_em = coalesce(p_paid_at, now()), notas = nullif(left(trim(coalesce(p_notes, '')), 1000), ''), updated_at = now() WHERE id = v_payout.id;

    IF v_client_id IS NOT NULL THEN
      INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
      VALUES (
        v_client_id,
        'Pagamento de Saque PIX Concluído 💰',
        format('O pagamento por PIX no valor de R$ %s foi realizado com sucesso para sua chave cadastrada.', to_char(v_payout.valor, 'FM999G999G990D00')),
        'afiliados', 'saques', 'cliente', 'pagamento_saque'
      );
    END IF;

  ELSE
    RAISE EXCEPTION 'Ação inválida. Use approve, reject ou mark_paid.';
  END IF;

  PERFORM public.gsa_admin_write_audit('afiliados','DECIDIR_SAQUE_AFILIADO','gsa_afiliado_saques',v_payout.id,jsonb_build_object('acao', v_action, 'valor', v_payout.valor, 'notas', p_notes));

  RETURN jsonb_build_object('success', true, 'payout_id', v_payout.id, 'status', (SELECT status FROM public.gsa_afiliado_saques WHERE id = v_payout.id));
END;

DECLARE
  v_actor record;
  v_emp emprestimos%rowtype;
  v_valor numeric := round(coalesce(p_valor_quitacao_acordo, 0), 2);
BEGIN
  IF v_valor <= 0 THEN RAISE EXCEPTION 'Valor da quitacao deve ser maior que zero.'; END IF;
  SELECT * INTO v_actor FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token) LIMIT 1;

  SELECT * INTO v_emp FROM public.emprestimos WHERE id = p_emprestimo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Emprestimo nao encontrado.'; END IF;

  IF coalesce(v_emp.status, '') <> 'analise_quitacao' THEN
    RETURN jsonb_build_object('success', true, 'already_processed', true, 'emprestimo_id', p_emprestimo_id, 'cliente_id', v_emp.cliente_id, 'status', v_emp.status);
  END IF;

  UPDATE public.emprestimos
     SET status = 'aguardando_pagamento_quitacao',
         valor_quitacao_acordo = v_valor,
         updated_at = now()
   WHERE id = p_emprestimo_id;

  PERFORM public.gsa_admin_emprestimo_add_historico(
    p_emprestimo_id,
    v_emp.orcamento_id,
    'oferta_quitacao',
    'Oferta de quitacao: R$ ' || to_char(v_valor, 'FM999999999990D00') || ' [POR: ' || v_actor.ator_nome || ']',
    'admin',
    NULL,
    jsonb_build_object('sessao_id', p_sessao_id)
  );

  RETURN jsonb_build_object('success', true, 'already_processed', false, 'emprestimo_id', p_emprestimo_id, 'cliente_id', v_emp.cliente_id, 'valor_quitacao_acordo', v_valor);
END;

DECLARE
  v_actor record;
  v_emp emprestimos%rowtype;
  v_valor numeric := round(coalesce(p_valor_aprovado, 0), 2);
  v_juros numeric := round(coalesce(p_juros_total_percentual, 0), 2);
  v_taxa numeric := round(coalesce(p_taxa_servico, 0), 2);
  v_parcelas integer := greatest(1, coalesce(p_max_parcelas_liberado, 1));
  v_validade integer := greatest(1, coalesce(p_validade_dias, 7));
BEGIN
  IF v_valor <= 0 THEN RAISE EXCEPTION 'Valor aprovado deve ser maior que zero.'; END IF;
  IF v_juros < 0 THEN RAISE EXCEPTION 'Juros nao pode ser negativo.'; END IF;
  IF v_taxa < 0 THEN RAISE EXCEPTION 'Taxa de servico nao pode ser negativa.'; END IF;

  SELECT * INTO v_actor FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token) LIMIT 1;
  SELECT * INTO v_emp FROM public.emprestimos WHERE id = p_emprestimo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Emprestimo nao encontrado.'; END IF;

  UPDATE public.emprestimos
     SET valor_aprovado = v_valor,
         juros_total_percentual = v_juros,
         max_parcelas_liberado = v_parcelas,
         taxa_servico = v_taxa,
         proposta_mensagem = p_proposta_mensagem,
         proposta_validade = now() + (v_validade || ' days')::interval,
         status = 'proposta_enviada',
         updated_at = now()
   WHERE id = p_emprestimo_id;

  IF v_emp.orcamento_id IS NOT NULL THEN
    UPDATE public.orcamentos SET status = 'aprovado' WHERE id = v_emp.orcamento_id;
  END IF;

  PERFORM public.gsa_admin_emprestimo_add_historico(
    p_emprestimo_id,
    v_emp.orcamento_id,
    'proposta_enviada',
    'Proposta: ' || v_juros || '% juros, max ' || v_parcelas || 'x, taxa R$' || v_taxa || ' [POR: ' || v_actor.ator_nome || ']',
    'admin',
    NULL,
