DECLARE
  v_actor record;
  v_count integer := 0;
  v_total_liberado numeric(14,2) := 0;
  v_rec record;
BEGIN
  PERFORM public.gsa_admin_validate_context(p_sessao_id, p_session_token);
  PERFORM public.gsa_admin_assert_module('afiliados');
  SELECT * INTO v_actor FROM public.gsa_admin_session_actor(p_sessao_id, p_session_token) LIMIT 1;

  IF p_afiliado_id IS NOT NULL THEN
    -- Antecipa carência de 1 afiliado específico
    IF NOT EXISTS (SELECT 1 FROM public.gsa_afiliados WHERE id = p_afiliado_id) THEN
      RAISE EXCEPTION 'Afiliado não encontrado.';
    END IF;

    SELECT coalesce(sum(valor), 0), count(*)
      INTO v_total_liberado, v_count
      FROM public.gsa_afiliado_comissoes
     WHERE afiliado_id = p_afiliado_id
       AND status = 'pendente';

    UPDATE public.gsa_afiliado_comissoes
       SET status = 'disponivel',
           disponivel_em = now(),
           updated_at = now()
     WHERE afiliado_id = p_afiliado_id
       AND status = 'pendente';

    IF v_count > 0 THEN
      INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
      VALUES (
        (SELECT cliente_id FROM public.gsa_afiliados WHERE id = p_afiliado_id),
        'Carência Antecipada! ⚡',
        format('Suas comissões em carência no valor de R$ %s foram liberadas antecipadamente pelo suporte administrativo.', to_char(v_total_liberado, 'FM999G999G990D00')),
        'afiliados', 'comissoes', 'cliente', 'antecipacao_carencia_afiliado'
      );
    END IF;

  ELSE
    -- Antecipa carência de TODOS os afiliados
    SELECT coalesce(sum(valor), 0), count(*)
      INTO v_total_liberado, v_count
      FROM public.gsa_afiliado_comissoes
     WHERE status = 'pendente';

    FOR v_rec IN
      SELECT a.cliente_id, sum(c.valor) as total_afiliado
        FROM public.gsa_afiliado_comissoes c
        JOIN public.gsa_afiliados a ON a.id = c.afiliado_id
       WHERE c.status = 'pendente'
       GROUP BY a.cliente_id
    LOOP
      INSERT INTO public.notificacoes(cliente_id, titulo, mensagem, modulo, tab, destinatario_tipo, acao_origem)
      VALUES (
        v_rec.cliente_id,
        'Carência Antecipada! ⚡',
        format('Suas comissões em carência no valor de R$ %s foram liberadas antecipadamente pelo suporte administrativo.', to_char(v_rec.total_afiliado, 'FM999G999G990D00')),
        'afiliados', 'comissoes', 'cliente', 'antecipacao_carencia_afiliado'
      );
    END LOOP;

    UPDATE public.gsa_afiliado_comissoes
       SET status = 'disponivel',
           disponivel_em = now(),
           updated_at = now()
     WHERE status = 'pendente';
  END IF;

  PERFORM public.gsa_admin_write_audit(
    'afiliados',
    'ANTECIPAR_CARENCIA_COMISSOES',
    'gsa_afiliado_comissoes',
    p_afiliado_id,
    jsonb_build_object(
      'afiliado_id', p_afiliado_id,
      'comissoes_liberadas', v_count,
      'valor_total_liberado', v_total_liberado,
      'ator', v_actor.ator_nome
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'count', v_count,
    'total_liberado', v_total_liberado,
    'afiliado_id', p_afiliado_id
  );
END;

