  PERFORM public.gsa_admin_write_audit('afiliados','ATUALIZAR_PONTOS_AFILIADO','system_settings',NULL,jsonb_build_object('taxa',p_rate,'minimo',p_minimum,'ativo',p_active));
  RETURN jsonb_build_object('success', true);
END;

DECLARE
  v_context jsonb;
  v_application public.gsa_careers_applications%ROWTYPE;
  v_new_status text := lower(trim(COALESCE(p_status, '')));
  v_actor_type text;
  v_actor_id uuid;
  v_actor_name text;
  v_public_message text;
BEGIN
  v_context := public.gsa_careers_admin_context(p_sessao_id, p_session_token);
  v_actor_type := COALESCE(v_context->>'actor_type', v_context->>'ator_tipo');
  v_actor_name := COALESCE(v_context->>'actor_name', v_context->>'ator_nome', 'Administrador');
  BEGIN
    v_actor_id := COALESCE(v_context->>'actor_id', v_context->>'ator_id')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor_id := NULL;
  END;

  IF v_new_status NOT IN ('received', 'under_review', 'interview_scheduled', 'approved', 'talent_pool', 'rejected') THEN
    RAISE EXCEPTION 'Status invalido' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_application
  FROM public.gsa_careers_applications
  WHERE id = p_application_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidatura nao encontrada' USING ERRCODE = 'P0002';
  END IF;

  IF v_new_status <> v_application.status AND NOT (
    (v_application.status = 'received' AND v_new_status IN ('under_review', 'talent_pool', 'rejected')) OR
    (v_application.status = 'under_review' AND v_new_status IN ('interview_scheduled', 'approved', 'talent_pool', 'rejected')) OR
    (v_application.status = 'interview_scheduled' AND v_new_status IN ('under_review', 'approved', 'talent_pool', 'rejected')) OR
    (v_application.status = 'talent_pool' AND v_new_status IN ('under_review', 'interview_scheduled', 'rejected')) OR
    (v_application.status = 'rejected' AND v_new_status = 'under_review') OR
    (v_application.status = 'approved' AND v_new_status = 'under_review')
  ) THEN
    RAISE EXCEPTION 'Transicao de status nao permitida: % para %', v_application.status, v_new_status
      USING ERRCODE = '22023';
  END IF;

  IF v_new_status = 'interview_scheduled' THEN
    IF p_interview_at IS NULL OR trim(COALESCE(p_interview_location, '')) = '' THEN
      RAISE EXCEPTION 'Data e local/link da entrevista sao obrigatorios' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_new_status = 'rejected' AND trim(COALESCE(p_internal_notes, '')) = '' THEN
    RAISE EXCEPTION 'O motivo interno do encerramento e obrigatorio' USING ERRCODE = '22023';
  END IF;

  v_public_message := CASE v_new_status
    WHEN 'received' THEN 'Candidatura recebida. A equipe de Recursos Humanos fará a análise inicial do perfil.'
    WHEN 'under_review' THEN 'Seu perfil está em análise pela equipe de Recursos Humanos.'
    WHEN 'interview_scheduled' THEN 'Você avançou para a etapa de entrevista. Consulte os dados de agendamento abaixo.'
    WHEN 'approved' THEN 'Você foi aprovado no processo seletivo. A equipe de Recursos Humanos entrará em contato para os próximos procedimentos.'
    WHEN 'talent_pool' THEN 'Seu perfil foi incluído em nosso Banco de Talentos para futuras oportunidades compatíveis.'
    WHEN 'rejected' THEN 'Este processo seletivo foi encerrado. Agradecemos seu interesse em fazer parte do Grupo GSA.'
  END;

  UPDATE public.gsa_careers_applications
  SET status = v_new_status,
      internal_notes = nullif(trim(COALESCE(p_internal_notes, '')), ''),
      public_message = v_public_message,
      interview_at = CASE WHEN v_new_status = 'interview_scheduled' THEN p_interview_at ELSE interview_at END,
      interview_location = CASE WHEN v_new_status = 'interview_scheduled' THEN trim(p_interview_location) ELSE interview_location END,
      status_changed_at = CASE WHEN v_new_status <> v_application.status THEN now() ELSE status_changed_at END,
      closed_at = CASE WHEN v_new_status IN ('approved', 'rejected') THEN now() ELSE NULL END,
      updated_at = now()
  WHERE id = p_application_id;

  IF v_new_status <> v_application.status THEN
    INSERT INTO public.gsa_careers_application_history (
      application_id,
      from_status,
      to_status,
      actor_type,
      actor_id,
      actor_name,
      note,
      interview_at,
      interview_location
    ) VALUES (
      p_application_id,
      v_application.status,
      v_new_status,
      v_actor_type,
      v_actor_id,
      v_actor_name,
      nullif(trim(COALESCE(p_internal_notes, '')), ''),
      CASE WHEN v_new_status = 'interview_scheduled' THEN p_interview_at ELSE NULL END,
      CASE WHEN v_new_status = 'interview_scheduled' THEN trim(p_interview_location) ELSE NULL END
    );
  END IF;

  RETURN public.gsa_admin_get_career_application(
    p_sessao_id,
    p_session_token,
    p_application_id
  );
END;

DECLARE
  v_contrib record;
  v_vaquinha record;
  v_novo_arrecadado numeric;
  v_nova_qtd integer;
  v_novo_status text;
BEGIN
  SELECT * INTO v_contrib FROM public.loja_vaquinha_contribuicoes WHERE id = p_contribuicao_id;
  IF v_contrib.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contribui????o n??o encontrada.');
  END IF;

  IF v_contrib.status = 'pago' THEN
    RETURN jsonb_build_object('success', true, 'message', 'Contribui????o j?? confirmada anteriormente.');
  END IF;

  UPDATE public.loja_vaquinha_contribuicoes
  SET status = 'pago',
      pago_em = now(),
      transacao_id = COALESCE(p_transacao_id, transacao_id, 'PIX-' || SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 10))
  WHERE id = p_contribuicao_id;

  SELECT 
    COALESCE(SUM(valor), 0.00),
    COUNT(*)
  INTO v_novo_arrecadado, v_nova_qtd
  FROM public.loja_vaquinha_contribuicoes
  WHERE vaquinha_id = v_contrib.vaquinha_id AND status = 'pago';

  SELECT * INTO v_vaquinha FROM public.loja_vaquinhas WHERE id = v_contrib.vaquinha_id;
  v_novo_status := CASE WHEN v_novo_arrecadado >= v_vaquinha.meta_valor THEN 'concluida' ELSE 'aberta' END;

  UPDATE public.loja_vaquinhas
  SET valor_arrecadado = v_novo_arrecadado,
      quantidade_contribuicoes = v_nova_qtd,
      status = v_novo_status,
      updated_at = now()
  WHERE id = v_contrib.vaquinha_id;

  RETURN jsonb_build_object(
    'success', true,
    'valor_arrecadado', v_novo_arrecadado,
    'quantidade_contribuicoes', v_nova_qtd,
    'status', v_novo_status,
    'meta_atingida', v_novo_arrecadado >= v_vaquinha.meta_valor
  );
END;

DECLARE
  v_codigo text;
  v_vaquinha record;
  v_meta numeric;
BEGIN
  v_codigo := 'VAQ-' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT || CLOCK_TIMESTAMP()::TEXT) FROM 1 FOR 6));

  v_meta := COALESCE((p_dados->>'meta_valor')::numeric, 0.00);
  IF v_meta <= 0 THEN
    RAISE EXCEPTION 'O valor da meta da vaquinha deve ser maior que zero.';
  END IF;

  INSERT INTO public.loja_vaquinhas (
    codigo,
    produto_id,
    produto_snapshot,
    organizador_nome,
    organizador_telefone,
    organizador_email,
    organizador_id,
    presenteado_nome,
    data_evento,
    mensagem,
    meta_valor,
    endereco_entrega
  ) VALUES (
    v_codigo,
    (p_dados->>'produto_id')::uuid,
    COALESCE(p_dados->'produto_snapshot', '{}'::jsonb),
    COALESCE(p_dados->>'organizador_nome', 'Organizador'),
    COALESCE(p_dados->>'organizador_telefone', ''),
    p_dados->>'organizador_email',
    (p_dados->>'organizador_id')::uuid,
    COALESCE(p_dados->>'presenteado_nome', 'Amigo(a)'),
    (p_dados->>'data_evento')::date,
    p_dados->>'mensagem',
    v_meta,
    p_dados->'endereco_entrega'
  )
  RETURNING * INTO v_vaquinha;

  RETURN jsonb_build_object(
    'success', true,
    'vaquinha', row_to_json(v_vaquinha)
  );
END;

DECLARE
  v_vaquinha record;
  v_contribuicoes jsonb;
  v_percentual numeric;
  v_restante numeric;
BEGIN
  IF p_codigo_ou_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    SELECT * INTO v_vaquinha FROM public.loja_vaquinhas WHERE id = p_codigo_ou_id::uuid;
  ELSE
    SELECT * INTO v_vaquinha FROM public.loja_vaquinhas WHERE LOWER(codigo) = LOWER(p_codigo_ou_id);
  END IF;

  IF v_vaquinha.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vaquinha n??o encontrada.');
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'contribuinte_nome', c.contribuinte_nome,
      'valor', c.valor,
      'mensagem', c.mensagem,
      'pago_em', c.pago_em,
      'created_at', c.created_at
    ) ORDER BY c.created_at DESC
  ), '[]'::jsonb)
  INTO v_contribuicoes
  FROM public.loja_vaquinha_contribuicoes c
  WHERE c.vaquinha_id = v_vaquinha.id AND c.status = 'pago';

  v_percentual := LEAST(100.00, ROUND((v_vaquinha.valor_arrecadado / GREATEST(v_vaquinha.meta_valor, 0.01)) * 100, 1));
  v_restante := GREATEST(0.00, v_vaquinha.meta_valor - v_vaquinha.valor_arrecadado);

  RETURN jsonb_build_object(
    'success', true,
    'vaquinha', row_to_json(v_vaquinha),
    'contribuicoes', v_contribuicoes,
    'percentual', v_percentual,
    'valor_restante', v_restante,
    'meta_atingida', v_vaquinha.valor_arrecadado >= v_vaquinha.meta_valor
  );
END;

DECLARE
  v_partner public.parceiros%ROWTYPE;
  v_nome text := trim(COALESCE(p_nome_completo, ''));
  v_telefone text := trim(COALESCE(p_telefone, ''));
  v_email text := nullif(trim(COALESCE(p_email, '')), '');
  v_clean_phone text;
  v_codigo_gerado text := NULL;
  v_tipo_resgate text := 'link';
  v_resgate_id uuid;
  v_rand_suffix text;
  v_year text := to_char(clock_timestamp(), 'YYYY');
BEGIN
  IF v_nome = '' OR length(v_nome) < 2 THEN
    RAISE EXCEPTION 'Informe seu nome completo para resgatar o benef??cio.' USING ERRCODE = '22023';
  END IF;

  v_clean_phone := regexp_replace(v_telefone, '\D', '', 'g');
  IF length(v_clean_phone) < 10 THEN
    RAISE EXCEPTION 'Informe um telefone com DDD v??lido para contato.' USING ERRCODE = '22023';
  END IF;

  IF p_parceiro_id IS NOT NULL THEN
    SELECT * INTO v_partner FROM public.parceiros WHERE id = p_parceiro_id AND status = 'ativo' LIMIT 1;
  ELSIF p_parceiro_slug IS NOT NULL AND p_parceiro_slug <> '' THEN
    SELECT * INTO v_partner FROM public.parceiros WHERE slug = lower(trim(p_parceiro_slug)) AND status = 'ativo' LIMIT 1;
  END IF;

  IF v_partner.id IS NULL THEN
    RAISE EXCEPTION 'Parceiro n??o encontrado ou inativo.' USING ERRCODE = 'P0002';
  END IF;

  v_rand_suffix := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
  v_codigo_gerado := 'PROT-RES-' || v_year || '-' || v_rand_suffix;

  IF v_partner.redemption_has_coupon THEN
    v_tipo_resgate := 'cupom';
    IF v_partner.redemption_coupon_code IS NOT NULL AND trim(v_partner.redemption_coupon_code) <> '' THEN
      v_codigo_gerado := upper(trim(v_partner.redemption_coupon_code));
    END IF;
  ELSIF v_partner.redemption_has_voucher THEN
    v_tipo_resgate := 'voucher';
  END IF;

  IF v_partner.redemption_has_link AND (v_partner.redemption_has_coupon OR v_partner.redemption_has_voucher) THEN
    v_tipo_resgate := 'combinado';
  END IF;

  IF COALESCE(v_partner.redemption_delay_24h, false) THEN
    v_tipo_resgate := 'manual_24h';
  END IF;

  INSERT INTO public.parceiros_resgates (
    parceiro_id,
    cliente_id,
    nome_completo,
    email,
    telefone,
    codigo_gerado,
    tipo_resgate,
    link_destino,
    status,
    auto_redirecionado
  ) VALUES (
    v_partner.id,
    p_cliente_id,
    v_nome,
    v_email,
    v_telefone,
    v_codigo_gerado,
    v_tipo_resgate,
    nullif(trim(COALESCE(v_partner.redemption_link, v_partner.website, '')), ''),
    'pendente',
    COALESCE(v_partner.redemption_auto_redirect, false)
  ) RETURNING id INTO v_resgate_id;

  RETURN jsonb_build_object(
    'success', true,
    'resgate_id', v_resgate_id,
    'partner_name', v_partner.name,
    'partner_slug', v_partner.slug,
    'partner_logo', v_partner.logo_url,
    'benefits', v_partner.benefits,
    'tipo_resgate', v_tipo_resgate,
    'codigo_gerado', v_codigo_gerado,
    'protocolo', v_codigo_gerado,
    'email', v_email,
    'telefone', v_telefone,
    'nome_completo', v_nome,
    'has_coupon', v_partner.redemption_has_coupon,
    'has_voucher', v_partner.redemption_has_voucher,
    'has_link', v_partner.redemption_has_link,
    'link', nullif(trim(COALESCE(v_partner.redemption_link, v_partner.website, '')), ''),
    'auto_redirect', COALESCE(v_partner.redemption_auto_redirect, false),
    'instructions', nullif(trim(COALESCE(v_partner.redemption_instructions, '')), ''),
    'delay_24h', COALESCE(v_partner.redemption_delay_24h, false)
  );
END;

DECLARE
